=head2 Google::Cloud::Migrationcenter::V1::Migrationcenter::VirtualMachinePreferences

VirtualMachinePreferences enables you to create sets of assumptions, for
example, a geographical location and pricing track, for your migrated virtual
machines. The set of preferences influence recommendations for migrating
virtual machine assets.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->target_product() >> / C<< $msg->target_product($value) >>

Type: C<Enum> (L<Google::Cloud::Migrationcenter::V1::ComputeMigrationTargetProduct>)

Target product for assets using this preference set.
Specify either target product or business goal, but
not both.

=item * C<< $msg->region_preferences() >> / C<< $msg->region_preferences($value) >>

Type: C<Message> (L<Google::Cloud::Migrationcenter::V1::Migrationcenter::RegionPreferences>)

Region preferences for assets using this preference set.
If you are unsure which value to set, the migration service API region is
often a good value to start with.

=item * C<< $msg->commitment_plan() >> / C<< $msg->commitment_plan($value) >>

Type: C<Enum> (L<Google::Cloud::Migrationcenter::V1::CommitmentPlan>)

Commitment plan to consider when calculating costs for virtual machine
insights and recommendations.
If you are unsure which value to set, a 3 year commitment plan is often a
good value to start with.

=item * C<< $msg->sizing_optimization_strategy() >> / C<< $msg->sizing_optimization_strategy($value) >>

Type: C<Enum> (L<Google::Cloud::Migrationcenter::V1::SizingOptimizationStrategy>)

Sizing optimization strategy specifies the preferred strategy used when
extrapolating usage data to calculate insights and recommendations for a
virtual machine.
If you are unsure which value to set, a moderate sizing optimization
strategy is often a good value to start with.

=item * C<< $msg->compute_engine_preferences() >> / C<< $msg->compute_engine_preferences($value) >>

Type: C<Message> (L<Google::Cloud::Migrationcenter::V1::Migrationcenter::ComputeEnginePreferences>)

Compute Engine preferences concern insights and recommendations for Compute
Engine target.

=item * C<< $msg->vmware_engine_preferences() >> / C<< $msg->vmware_engine_preferences($value) >>

Type: C<Message> (L<Google::Cloud::Migrationcenter::V1::Migrationcenter::VmwareEnginePreferences>)

Preferences concerning insights and recommendations for
Google Cloud VMware Engine.

=item * C<< $msg->sole_tenancy_preferences() >> / C<< $msg->sole_tenancy_preferences($value) >>

Type: C<Message> (L<Google::Cloud::Migrationcenter::V1::Migrationcenter::SoleTenancyPreferences>)

Preferences concerning Sole Tenant nodes and virtual machines.

=back

=head2 Google::Cloud::Migrationcenter::V1::Migrationcenter::ComputeEnginePreferences

The user preferences relating to Compute Engine target platform.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->machine_preferences() >> / C<< $msg->machine_preferences($value) >>

Type: C<Message> (L<Google::Cloud::Migrationcenter::V1::Migrationcenter::MachinePreferences>)

Preferences concerning the machine types to consider on Compute Engine.

=item * C<< $msg->license_type() >> / C<< $msg->license_type($value) >>

Type: C<Enum> (L<Google::Cloud::Migrationcenter::V1::LicenseType>)

License type to consider when calculating costs for virtual machine
insights and recommendations. If unspecified, costs are calculated
based on the default licensing plan.

=back

=head2 Google::Cloud::Migrationcenter::V1::Migrationcenter::MachinePreferences

The type of machines to consider when calculating virtual machine migration
insights and recommendations.
Not all machine types are available in all zones and regions.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->allowed_machine_series() >> / C<< $msg->allowed_machine_series($value) >>

Type: C<Message> (L<Google::Cloud::Migrationcenter::V1::Migrationcenter::MachineSeries>)

Compute Engine machine series to consider for insights and recommendations.
If empty, no restriction is applied on the machine series.

=back

=head2 Google::Cloud::Migrationcenter::V1::Migrationcenter::MachineSeries

A Compute Engine machine series.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->code() >> / C<< $msg->code($value) >>

Type: C<String>

Code to identify a Compute Engine machine series. Consult
https://cloud.google.com/compute/docs/machine-resource#machine_type_comparison
for more details on the available series.

=back

=head2 Google::Cloud::Migrationcenter::V1::Migrationcenter::VmwareEnginePreferences

The user preferences relating to Google Cloud VMware Engine target platform.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->cpu_overcommit_ratio() >> / C<< $msg->cpu_overcommit_ratio($value) >>

Type: C<Double>

CPU overcommit ratio.
Acceptable values are between 1.0 and 8.0, with 0.1 increment.

=item * C<< $msg->memory_overcommit_ratio() >> / C<< $msg->memory_overcommit_ratio($value) >>

Type: C<Double>

Memory overcommit ratio.
Acceptable values are 1.0, 1.25, 1.5, 1.75 and 2.0.

=item * C<< $msg->storage_deduplication_compression_ratio() >> / C<< $msg->storage_deduplication_compression_ratio($value) >>

Type: C<Double>

The Deduplication and Compression ratio is based on the logical (Used
Before) space required to store data before applying deduplication and
compression, in relation to the physical (Used After) space required after
applying deduplication and compression. Specifically, the ratio is the Used
Before space divided by the Used After space. For example, if the Used
Before space is 3 GB, but the physical Used After space is 1 GB, the
deduplication and compression ratio is 3x. Acceptable values are
between 1.0 and 4.0.

=item * C<< $msg->commitment_plan() >> / C<< $msg->commitment_plan($value) >>

Type: C<Enum> (L<Google::Cloud::Migrationcenter::V1::VmwareEnginePreferences::CommitmentPlan>)

Commitment plan to consider when calculating costs for virtual machine
insights and recommendations.
If you are unsure which value to set, a 3 year commitment plan is often a
good value to start with.

=back

=head3 Enum: VmwareEnginePreferences::CommitmentPlan

=over 4

=item * C<COMMITMENT_PLAN_UNSPECIFIED> => C<0>

=item * C<ON_DEMAND> => C<1>

=item * C<COMMITMENT_1_YEAR_MONTHLY_PAYMENTS> => C<2>

=item * C<COMMITMENT_3_YEAR_MONTHLY_PAYMENTS> => C<3>

=item * C<COMMITMENT_1_YEAR_UPFRONT_PAYMENT> => C<4>

=item * C<COMMITMENT_3_YEAR_UPFRONT_PAYMENT> => C<5>

=back

